<?php get_header(); ?>
<main id="main" class="wrap"><?php while ( have_posts() ) : the_post(); $project = 'adi_project' === get_post_type(); $publication = 'adi_publication' === get_post_type(); ?>
<article <?php post_class( 'single-entry' ); ?>><header class="article-header"><a class="back-link" href="<?php echo esc_url( $project ? adi_projects_url() : ( $publication ? get_post_type_archive_link( 'adi_publication' ) : adi_page_url( 'writing' ) ) ); ?>">← <?php echo esc_html( $project ? 'All projects' : ( $publication ? 'Publications' : 'Writing' ) ); ?></a><p class="eyebrow"><?php echo esc_html( $project || $publication ? get_post_meta( get_the_ID(), 'adi_format', true ) : get_the_date( 'F j, Y' ) . ' · ' . adi_reading_minutes( get_the_content() ) . ' min read' ); ?></p><h1><?php the_title(); ?></h1><?php if ( has_excerpt() ) : ?><p class="article-deck"><?php echo esc_html( get_the_excerpt() ); ?></p><?php endif; ?></header>
<?php if ( $project ) : ?><div class="case-meta"><?php foreach ( array( 'adi_role' => 'My role', 'adi_year' => 'Period', 'adi_outcome' => 'In focus' ) as $key => $label ) : $value = get_post_meta( get_the_ID(), $key, true ); if ( ! $value ) { continue; } ?><div><span class="small-label"><?php echo esc_html( $label ); ?></span><p><?php echo esc_html( $value ); ?></p></div><?php endforeach; ?></div><div class="case-visual"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'full' ); else : adi_visual( get_post_meta( get_the_ID(), 'adi_visual', true ) ?: 'canvas' ); endif; ?></div><?php elseif ( has_post_thumbnail() ) : ?><div class="article-cover"><?php the_post_thumbnail( 'full' ); ?></div><?php endif; ?>
<div class="article-body entry-content"><?php the_content(); wp_link_pages(); ?><?php if ( $publication && get_post_meta( get_the_ID(), 'adi_citation', true ) ) : ?><blockquote><?php echo esc_html( get_post_meta( get_the_ID(), 'adi_citation', true ) ); ?></blockquote><?php endif; ?></div>
<?php $source = get_post_meta( get_the_ID(), 'adi_source_url', true ); if ( $source ) : ?><div class="article-source"><a class="text-link" href="<?php echo esc_url( $source ); ?>">View the source record <?php echo adi_arrow(); ?></a></div><?php endif; ?>
<div class="article-end"><p>Questions, thoughts, or a different perspective?</p><a class="text-link" href="#contact">Let’s talk <?php echo adi_arrow(); ?></a><button class="copy-link" type="button" data-copy-link>Copy page link</button><span class="sr-only copy-status" aria-live="polite"></span></div></article>
<?php if ( $project ) : $related = new WP_Query( array( 'post_type' => 'adi_project', 'post__not_in' => array( get_the_ID() ), 'posts_per_page' => 2, 'orderby' => 'menu_order', 'order' => 'ASC' ) ); ?><section class="section related"><div class="section-heading"><div><p class="eyebrow">Keep exploring</p><h2>A different lens.</h2></div></div><div class="project-grid"><?php while ( $related->have_posts() ) : $related->the_post(); get_template_part( 'template-parts/project-card' ); endwhile; wp_reset_postdata(); ?></div></section><?php endif; ?>
<?php endwhile; ?></main><?php get_footer(); ?>
